A.aSz=new B.am("filament","CALIBRA\xc7\xc3O","Primeira camada est\xe1vel","Ajuste mesa, bico e offset Z antes de imprimir.",A.aIA,"Se o bico tocar a mesa, suba o offset Z aos poucos.",null)
A.akD=s(["Seque o filamento se estalar, borbulhar ou deixar fios.","Guarde bobinas em local seco com s\xedlica gel.","Fa\xe7a uma torre de temperatura e ajuste a retra\xe7\xe3o."],t.s)
A.aSO=new B.am("filament","QUALIDADE","Muitos fiapos","Verifique umidade, temperatura e retra\xe7\xe3o.",A.akD,"Cada material seca em uma temperatura diferente.","dryer")
A.aES=s(["Remova gordura e poeira da mesa.","Use brim em bases pequenas ou cantos grandes.","Aplique uma camada fina de adesivo 3D quando compat\xedvel."],t.s)
A.aTp=new B.am("filament","ADER\xcaNCIA","A pe\xe7a descola da mesa","Melhore a ader\xeancia sem danificar a superf\xedcie.",A.aES,"Espere a mesa esfriar antes de usar ferramentas.","adhesive")
A.aE5=s(["Use luvas de nitrilo antes de tocar resina l\xedquida.","Trabalhe em local ventilado.","Cure suportes e res\xedduos antes de descartar."],t.s)
A.aU3=new B.am("resin","SEGURAN\xc7A","Manuseio seguro de resina","Proteja pele, olhos e ventila\xe7\xe3o.",A.aE5,"N\xe3o jogue resina ou \xe1lcool contaminado no ralo.",null)
